const odin_system = {
  buildParams(imports, params) {
    const dim = imports.array.getDimObj();
    const odin = {};
    const N = imports.io.readReal(params, "N", 1e+06);
    const I0 = imports.io.readReal(params, "I0", 1);
    const beta = imports.io.readReal(params, "beta", 4);
    const sigma = imports.io.readReal(params, "sigma", 2);
    const shape = new Map([
      ["S", []],
      ["I", []],
      ["R", []]
    ]);
    odin.packing = new imports.Packer({ shape });
    params.N = N;
    params.I0 = I0;
    params.beta = beta;
    params.sigma = sigma;
    return { ...params, dim, odin };
  },
  buildInternal(imports, params) {
    return {};
  },
  initial(imports, time, params, internal, state) {
    state[0] = params.N - params.I0;
    state[1] = params.I0;
    state[2] = 0;
  },
  rhs(imports, params, internal, time, state, stateDeriv) {
    const unpacked = params.odin.packing.unpackArray(state);
    const S = unpacked.get('S');
    const I = unpacked.get('I');
    stateDeriv[0] = -params.beta * S * I / params.N;
    stateDeriv[1] = params.beta * S * I / params.N - params.sigma * I;
    stateDeriv[2] = params.sigma * I;
  },
};
odin_system;
